INSERT INTO lessons (id, course, category, categoryKey, categoryNum, title, chineseTitle, pinyin, meaning, level, description, videoUrl, posterUrl, fullAudio, keywords, accessType, price) VALUES ('hsk2-01', 'HSK 2', 'HSK 2', 'hsk2', 'Course 1', 'She treated us to Peking Duck', '她请我们吃了北京烤鸭', 'Tā qǐng wǒmen chī le Běijīng kǎoyā', 'She treated us to Peking Duck', 'HSK 2', 'Practice HSK 2 expressions with 请 (to treat someone), completed-action 了 (le), and talking about Chinese dishes featuring Peking Duck (北京烤鸭).', 'assets/video/lesson-02.mp4', 'assets/images/story-02.jpg', 'assets/audio/lesson-02-full.mp3', 'HSK 2, 北京烤鸭, Peking Duck, 请, 吃了', 'paid', 75000);
INSERT INTO vocabulary (lessonId, "order", character, pinyin, meaning, audio) VALUES ('hsk2-01', 1, '请', 'qǐng', 'to treat / invite someone', 'assets/audio/tian-haochi.mp3');
INSERT INTO vocabulary (lessonId, "order", character, pinyin, meaning, audio) VALUES ('hsk2-01', 2, '我们', 'wǒmen', 'we / us', 'assets/audio/tian-haochi.mp3');
INSERT INTO vocabulary (lessonId, "order", character, pinyin, meaning, audio) VALUES ('hsk2-01', 3, '吃', 'chī', 'to eat', 'assets/audio/tian-haochi.mp3');
INSERT INTO vocabulary (lessonId, "order", character, pinyin, meaning, audio) VALUES ('hsk2-01', 4, '了', 'le', 'completed action marker', 'assets/audio/tian-haochi.mp3');
INSERT INTO vocabulary (lessonId, "order", character, pinyin, meaning, audio) VALUES ('hsk2-01', 5, '北京烤鸭', 'Běijīng kǎoyā', 'Peking Duck', 'assets/audio/shichang.mp3');
INSERT INTO vocabulary (lessonId, "order", character, pinyin, meaning, audio) VALUES ('hsk2-01', 6, '买单', 'mǎidān', 'pay the bill', 'assets/audio/dianyingyuan.mp3');
INSERT INTO writing_characters (lessonId, "order", character, pinyin, meaning, strokeCount, radical, strokeAnimationUrl, svgPath, strokeOrderSteps) VALUES ('hsk2-01', 1, '请', 'qǐng', 'to treat / invite / please', 10, '讠 (Speech)', '', '', '1. Dot (丶), 2. Horizontal-turn-lift (㇊), 3. Horizontal (一), 4. Horizontal (一), 5. Vertical (丨), 6. Horizontal (一), 7. Vertical (丨), 8. Horizontal-turn-hook (𠃌), 9. Horizontal (一), 10. Horizontal (一)');
INSERT INTO writing_characters (lessonId, "order", character, pinyin, meaning, strokeCount, radical, strokeAnimationUrl, svgPath, strokeOrderSteps) VALUES ('hsk2-01', 2, '鸭', 'yā', 'duck', 10, '鸟 (Bird)', '', '', '1. Vertical (丨), 2. Horizontal-turn (𠃍), 3. Horizontal (一), 4. Horizontal (一), 5. Vertical (丨), 6. Slant (丿), 7. Horizontal-turn-hook (𠃌), 8. Dot (丶), 9. Vertical-turn-hook (㇉), 10. Horizontal (一)');
INSERT INTO writing_characters (lessonId, "order", character, pinyin, meaning, strokeCount, radical, strokeAnimationUrl, svgPath, strokeOrderSteps) VALUES ('hsk2-01', 3, '吃', 'chī', 'to eat', 6, '口 (Mouth)', '', '', '1. Vertical (丨), 2. Horizontal-turn (𠃍), 3. Horizontal (一), 4. Top slant (丿), 5. Horizontal (一), 6. Curved hook (乙)');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 1, 'listening', '', '', '', 'Listen to the sentence and choose the matching picture.', '', '她请我们吃了北京烤鸭。', '北京烤鸭 (Peking Duck)', '牛肉面 (Beef noodles)', '冰茶 (Iced tea)', '', '', 'assets/images/exercises/roast-duck.svg', 'assets/images/exercises/noodles-bowl.svg', 'assets/images/exercises/iced-tea-cup.svg', '', '', 'A', '她请我们吃了北京烤鸭 (Tā qǐng wǒmen chī le Běijīng kǎoyā) means "She treated us to Peking Duck" (Picture A).');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 2, 'listening', '', '', '', 'Listen to the audio. What main dish did she treat us to last night?', '', '昨天晚上她请我们去餐厅吃晚饭，点了一只北京烤鸭。', '北京烤鸭 (Peking Duck)', '牛肉面 (Beef noodles)', '菜单 (Menu)', '冰茶 (Iced tea)', '', '', '', '', '', '', 'A', 'The speaker says 点了一只北京烤鸭 ("ordered a Peking Duck"), so A is correct.');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 3, 'listening', '', '', '', 'Listen to the customer ordering. What drinks did they order with the Peking Duck?', '', '服务员，请给我们一份北京烤鸭，再来两杯冰茶。', 'Two cups of hot coffee', 'Two glasses of iced tea', 'One bowl of beef noodles', 'Three bottles of water', '', '', '', '', '', '', 'B', '两杯冰茶 (liǎng bēi bīngchá) means "two glasses of iced tea".');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 4, 'listening', '', '', '', 'Listen and choose what she did after eating Peking Duck.', '', '吃完北京烤鸭以后，她走去服务台买单了。', 'She ordered another roast duck', 'She asked the waiter for the menu', 'She went to the counter to pay the bill', 'She went home by taxi', '', '', '', '', '', '', 'C', '走去服务台买单了 (zǒu qù fúwùtái mǎidān le) means "walked to the service counter to pay the bill".');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 5, 'multiple-choice', '', '', '', 'What does ''她请我们吃了北京烤鸭'' (Tā qǐng wǒmen chī le Běijīng kǎoyā) mean?', '', '', 'She treated us to Peking Duck', 'We invited her to cook noodles', 'She ordered two cups of green tea', 'We walked to a Beijing supermarket', '', '', '', '', '', '', 'She treated us to Peking Duck', '请 (qǐng) means to treat or invite, 吃了 (chī le) means ate, and 北京烤鸭 (Běijīng kǎoyā) is Peking Duck.');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 6, 'multiple-choice', '', '', '', 'In the sentence ''她请我们吃了北京烤鸭'', what does the character 请 (qǐng) express?', '', '', 'To treat / pay for a meal for others', 'To ask for directions to the station', 'To arrive late for dinner', 'To return home by taxi', '', '', '', '', '', '', 'To treat / pay for a meal for others', '请 + someone + verb (e.g. 请我们吃饭) means to treat someone to food or drink.');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 7, 'image-choice', '', '', '', '昨天晚上她请我们吃了香喷喷的北京烤鸭。(Last night she treated us to delicious Peking Duck.) Choose the matching picture.', 'assets/audio/tian-haochi.mp3', '', '北京烤鸭 (Peking Duck)', '冰茶 (Iced tea)', '菜单 (Menu)', '', '', 'assets/images/exercises/roast-duck.svg', 'assets/images/exercises/iced-tea-cup.svg', 'assets/images/exercises/menu-book.svg', '', '', 'A', '北京烤鸭 (Běijīng kǎoyā) matches the roasted Peking Duck platter in picture A.');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 8, 'shared-image-match', 'hsk2-duck-pic', 'Part II: Match Picture A, B, C, or D to each HSK 2 dining sentence.', 'Běijīng kǎoyā yòu xiāng yòu cuì, wǒmen dōu hěn xǐhuan chī.', '北京烤鸭又香又脆，大家都非常喜欢吃。', '', '', '北京烤鸭 (Peking Duck)', '牛肉面 (Noodles)', '菜单 (Menu)', '买单 (Bill)', '', 'assets/images/exercises/roast-duck.svg', 'assets/images/exercises/noodles-bowl.svg', 'assets/images/exercises/menu-book.svg', 'assets/images/exercises/bill-receipt.svg', '', 'A', '北京烤鸭 (Běijīng kǎoyā) refers to roasted Peking Duck (A).');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 9, 'shared-image-match', 'hsk2-duck-pic', 'Part II: Match Picture A, B, C, or D to each HSK 2 dining sentence.', 'Chī wán kǎoyā yǐhòu, tā qù mǎidān le.', '吃完烤鸭以后，她走去服务台买单了。', '', '', '北京烤鸭 (Peking Duck)', '牛肉面 (Noodles)', '菜单 (Menu)', '买单 (Bill)', '', 'assets/images/exercises/roast-duck.svg', 'assets/images/exercises/noodles-bowl.svg', 'assets/images/exercises/menu-book.svg', 'assets/images/exercises/bill-receipt.svg', '', 'D', '买单 (mǎidān) means to pay the check/bill (D).');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 10, 'shared-text-match', 'hsk2-duck-bank', 'Sentence & Word Bank: Pick the best word (A–E) for each blank.', 'Jīntiān shì tā de shēngrì, tā (   ) wǒmen chī wǎnfàn.', '今天是她的生日，她 (   ) 我们去餐厅吃晚饭。', '', '', '请 (qǐng)', '吃 (chī)', '烤鸭 (kǎoyā)', '了 (le)', '买单 (mǎidān)', '', '', '', '', '', 'A', '她请我们去餐厅吃晚饭 means "She treated us to dinner at a restaurant."');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 11, 'shared-text-match', 'hsk2-duck-bank', 'Sentence & Word Bank: Pick the best word (A–E) for each blank.', 'Zhuō shàng de Běijīng (   ) zhēn hǎochī!', '桌上的北京 (   ) 又香又好吃！', '', '', '请 (qǐng)', '吃 (chī)', '烤鸭 (kǎoyā)', '了 (le)', '买单 (mǎidān)', '', '', '', '', '', 'C', '北京烤鸭 (Běijīng kǎoyā) means Peking Duck (C).');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 12, 'fill-blank', '', '', 'qǐng', '昨天晚上她 (   ) 我们吃了北京烤鸭。', '', '', '', '', '', '', '', '', '', '', '', '', '请', '请 (qǐng) means to treat or invite someone to eat.');
INSERT INTO exercises (lessonId, "order", type, groupId, groupTitle, pinyin, question, audioUrl, audioText, optionA, optionB, optionC, optionD, optionE, optionAImage, optionBImage, optionCImage, optionDImage, optionEImage, answer, explanation) VALUES ('hsk2-01', 13, 'fill-blank', '', '', 'chī', '周末我们一起去北京餐厅 (   ) 烤鸭。', '', '', '', '', '', '', '', '', '', '', '', '', '吃', '吃 (chī) means to eat.');
